public static class Solution
{
    public static string Describe(object? value) => value switch
    {
        null => "nothing",
        0 => "zero",
        int n => n < 0 ? "negative int" : "positive int",
        "" => "empty text",
        string s => $"text of length {s.Length}",
        List<int> list => $"list of {list.Count}",
        _ => "something else",
    };

    public static decimal TicketPrice(int? age, bool student) => (age, student) switch
    {
        (null, _) => 12m,
        (< 4, _) => 0m,
        (<= 12, _) => 6m,
        (>= 65, _) => 7m,
        (<= 25, true) => 8m,
        _ => 12m,
    };

    public static string Summarize(int[] values) => values switch
    {
        [] => "none",
        [var only] => $"just {only}",
        [var a, var b] => $"{a} and {b}",
        [var first, .., var last] => $"{first} ... {last} ({values.Length} items)",
    };
}

unitTests:
Test("describing values", () =>
{
    CheckEq(Describe(null), "nothing");
    CheckEq(Describe(0), "zero");
    CheckEq(Describe(-3), "negative int");
    CheckEq(Describe(8), "positive int");
    CheckEq(Describe(""), "empty text");
    CheckEq(Describe("hello"), "text of length 5");
    CheckEq(Describe(new List<int> { 1, 2 }), "list of 2");
    CheckEq(Describe(2.5), "something else");
    CheckEq(Describe(new List<string>()), "something else");
});

Test("ticket prices", () =>
{
    CheckEq(TicketPrice(null, true), 12m);
    CheckEq(TicketPrice(3, false), 0m);
    CheckEq(TicketPrice(4, false), 6m);
    CheckEq(TicketPrice(12, true), 6m);
    CheckEq(TicketPrice(13, true), 8m);
    CheckEq(TicketPrice(25, true), 8m);
    CheckEq(TicketPrice(26, true), 12m);
    CheckEq(TicketPrice(20, false), 12m);
    CheckEq(TicketPrice(70, true), 7m);
});

Test("list patterns", () =>
{
    CheckEq(Summarize([]), "none");
    CheckEq(Summarize([7]), "just 7");
    CheckEq(Summarize([1, 2]), "1 and 2");
    CheckEq(Summarize([5, 6, 7, 8]), "5 ... 8 (4 items)");
});

